import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Calendar, Clock, User, Stethoscope, FileText, Activity, Layers, Star } from 'lucide-react';
import { appointmentService, reviewService } from '../services/api';
import { Card, Button, StatusBadge, Spinner, PageHeader } from '../components/UI';
import { format } from 'date-fns';
import toast from 'react-hot-toast';

export default function AppointmentDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [appt, setAppt] = useState(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [reviewForm, setReviewForm] = useState({
    rating: 5,
    title: '',
    comment: '',
  });
  const [reviewErrors, setReviewErrors] = useState({});

  useEffect(() => {
    fetchAppt();
  }, [id]);

  async function fetchAppt() {
    try {
      const res = await appointmentService.getById(id);
      setAppt(res.data);
    } catch {
      toast.error('Appointment not found');
      navigate('/appointments');
    } finally {
      setLoading(false);
    }
  }

  async function handleCancel() {
    if (!window.confirm('Cancel this appointment?')) return;
    setActionLoading(true);
    try {
      await appointmentService.cancel(id);
      toast.success('Appointment cancelled');
      fetchAppt();
    } catch {
      toast.error('Failed to cancel');
    } finally {
      setActionLoading(false);
    }
  }

  async function handleComplete() {
    setActionLoading(true);
    try {
      await appointmentService.complete(id);
      toast.success('Appointment completed');
      fetchAppt();
    } catch {
      toast.error('Failed to complete');
    } finally {
      setActionLoading(false);
    }
  }

  async function handleReviewSubmit(e) {
    e.preventDefault();
    if (!validateReviewForm()) return;

    try {
      setActionLoading(true);
      const userStr = localStorage.getItem('medibook_user');
      const user = JSON.parse(userStr);

      const reviewData = {
        appointmentId: appt.appointmentId,
        providerId: appt.providerId,
        patientId: user.userId || 'patient-001',
        rating: parseInt(reviewForm.rating),
        title: reviewForm.title,
        comment: reviewForm.comment,
        reviewDate: new Date().toISOString(),
        isVerified: false,
      };

      const response = await reviewService.createReview(reviewData);
      toast.success('Review submitted successfully!');
      setShowReviewModal(false);
      setReviewForm({
        rating: 5,
        title: '',
        comment: '',
      });
      setReviewErrors({});
    } catch (error) {
      console.error('Review submission failed:', error);
      toast.error('Failed to submit review');
    } finally {
      setActionLoading(false);
    }
  }

  function validateReviewForm() {
    const e = {};
    if (!reviewForm.title.trim()) e.title = 'Review title is required';
    if (!reviewForm.comment.trim()) e.comment = 'Review comment is required';
    if (reviewForm.rating < 1 || reviewForm.rating > 5) e.rating = 'Rating must be between 1 and 5';

    setReviewErrors(e);
    return Object.keys(e).length === 0;
  }

  function renderStars(rating, interactive = false) {
    return (
      <div style={{ display: 'flex', gap: '4px' }}>
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            size={interactive ? 20 : 16}
            style={{
              color: star <= rating ? '#fbbf24' : '#d1d5db',
              cursor: interactive ? 'pointer' : 'default',
              transition: 'color 0.2s',
            }}
            fill={star <= rating}
            onClick={interactive ? () => setReviewForm({ ...reviewForm, rating: star }) : undefined}
          />
        ))}
      </div>
    );
  }

  const fmt = (d) => { try { return format(new Date(d), 'MMMM dd, yyyy'); } catch { return d; } };
  const fmtDt = (d) => { try { return format(new Date(d), 'MMM dd, yyyy · HH:mm'); } catch { return d; } };
  const fmtTime = (t) => {
    if (!t) return '—';
    const p = t.toString().split(':');
    const h = parseInt(p[0]);
    return `${h % 12 || 12}:${p[1]} ${h >= 12 ? 'PM' : 'AM'}`;
  };

  if (loading) return <div style={{ display: 'flex', justifyContent: 'center', padding: 80 }}><Spinner size={36} /></div>;
  if (!appt) return null;

  const infoItems = [
    { icon: User, label: 'Patient ID', value: appt.patientId },
    { icon: Stethoscope, label: 'Provider ID', value: appt.providerId },
    { icon: Layers, label: 'Slot ID', value: appt.slotId },
    { icon: Activity, label: 'Service Type', value: appt.serviceType },
    { icon: Calendar, label: 'Appointment Date', value: fmt(appt.appointmentDate) },
    { icon: Clock, label: 'Start Time', value: fmtTime(appt.startTime) },
    { icon: Clock, label: 'End Time', value: fmtTime(appt.endTime) },
    { icon: Activity, label: 'Mode', value: appt.modeOfConsultation },
  ];

  return (
    <div className="animate-fade-up">
      <PageHeader
        title="Appointment Details"
        subtitle={`ID: ${appt.appointmentId}`}
        action={
          <Button variant="ghost" onClick={() => navigate(-1)}>
            <ArrowLeft size={16} /> Back
          </Button>
        }
      />

      <div style={styles.layout}>
        {/* Main info */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
          <Card style={{ padding: 0, overflow: 'hidden' }}>
            {/* Header strip */}
            <div style={styles.apptHeader}>
              <div>
                <p style={styles.apptHeaderLabel}>Status</p>
                <StatusBadge status={appt.status} />
              </div>
              <div>
                <p style={styles.apptHeaderLabel}>Service</p>
                <p style={styles.apptHeaderValue}>{appt.serviceType}</p>
              </div>
              <div>
                <p style={styles.apptHeaderLabel}>Date</p>
                <p style={styles.apptHeaderValue}>{fmt(appt.appointmentDate)}</p>
              </div>
              <div>
                <p style={styles.apptHeaderLabel}>Time</p>
                <p style={styles.apptHeaderValue}>{fmtTime(appt.startTime)} – {fmtTime(appt.endTime)}</p>
              </div>
            </div>

            {/* Detail grid */}
            <div style={styles.detailGrid}>
              {infoItems.map(({ icon: Icon, label, value }) => (
                <div key={label} style={styles.detailItem}>
                  <div style={styles.detailIcon}><Icon size={16} color="var(--teal)" /></div>
                  <div>
                    <p style={styles.detailLabel}>{label}</p>
                    <p style={styles.detailValue}>{value}</p>
                  </div>
                </div>
              ))}
            </div>

            {appt.notes && (
              <div style={styles.notesSection}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                  <FileText size={15} color="var(--text-muted)" />
                  <span style={styles.detailLabel}>Notes</span>
                </div>
                <p style={{ fontSize: '0.92rem', lineHeight: 1.6, color: 'var(--text)' }}>{appt.notes}</p>
              </div>
            )}
          </Card>
        </div>

        {/* Sidebar */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {/* Actions */}
          <Card style={{ padding: 20 }}>
            <h3 style={styles.sideTitle}>Actions</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {appt.status === 'Scheduled' && (
                <>
                  <Button onClick={() => navigate(`/appointments/${id}/reschedule`)} style={{ justifyContent: 'center' }}>
                    <Calendar size={15} /> Reschedule
                  </Button>
                  <Button variant="ghost" onClick={handleComplete} disabled={actionLoading} style={{ justifyContent: 'center', background: '#dcfce7', color: '#15803d', border: 'none' }}>
                    Mark as Completed
                  </Button>
                  <Button variant="danger" onClick={handleCancel} disabled={actionLoading} style={{ justifyContent: 'center' }}>
                    Cancel Appointment
                  </Button>
                </>
              )}
              {appt.status !== 'Scheduled' && (
                <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', textAlign: 'center', padding: '8px 0' }}>
                  No actions available for <strong>{appt.status}</strong> appointment.
                </p>
              )}
            </div>
          </Card>

          {/* Timestamps */}
          <Card style={{ padding: 20 }}>
            <h3 style={styles.sideTitle}>Timeline</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {[['Created', appt.createdAt], ['Last Updated', appt.updatedAt]].map(([k, v]) => (
                <div key={k}>
                  <p style={{ fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>{k}</p>
                  <p style={{ fontSize: '0.88rem', marginTop: 2 }}>{fmtDt(v)}</p>
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

const styles = {
  layout: { display: 'grid', gridTemplateColumns: '1fr 280px', gap: 20 },
  apptHeader: {
    display: 'grid', gridTemplateColumns: 'repeat(4,1fr)',
    padding: '20px 24px', background: 'var(--ink)', gap: 24,
  },
  apptHeaderLabel: { fontSize: '0.72rem', fontWeight: 600, color: 'rgba(255,255,255,0.4)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 6 },
  apptHeaderValue: { fontSize: '0.92rem', fontWeight: 500, color: '#fff' },
  detailGrid: {
    display: 'grid', gridTemplateColumns: '1fr 1fr',
    gap: 0, padding: '8px 0',
  },
  detailItem: {
    display: 'flex', alignItems: 'flex-start', gap: 12,
    padding: '14px 24px', borderBottom: '1px solid var(--border)',
  },
  detailIcon: {
    width: 32, height: 32, borderRadius: 8,
    background: 'var(--teal-light)', display: 'flex',
    alignItems: 'center', justifyContent: 'center', flexShrink: 0,
  },
  detailLabel: { fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' },
  detailValue: { fontSize: '0.9rem', fontWeight: 500, marginTop: 2 },
  notesSection: {
    padding: '20px 24px', borderTop: '1px solid var(--border)',
    background: 'var(--surface)',
  },
  sideTitle: { fontSize: '0.82rem', fontWeight: 600, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 14 },
};
